function Get-PostBody($file) {
  $content = Get-Content $file -Raw
  $lines = $content -split "`n"
  $title = ""
  $inBody = $false
  $body = @()
  for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    if ($line -match 'wp-block-post-title">(.*)</h2>') {
      $title = $Matches[1]
    }
    if ($line -match 'entry-content wp-block-post-content') {
      $inBody = $true
    }
    if ($inBody) {
      $body += $line
      if ($line -match 'jp-post-flair|sharedaddy') {
        break
      }
    }
  }
  Write-Host "=== $file ==="
  Write-Host "TITLE: $title"
  $bodyText = ($body -join "`n").Substring(0, [Math]::Min(4000, ($body -join "`n").Length))
  Write-Host $bodyText
  Write-Host "---END---`n"
}

